#include <Cellerator/compiler/ir/realization/implement_generation_readiness_and_publication_v1.hh>
#include <set>
#include <tuple>
namespace cellerator::compiler::ir::realization::v1 {namespace{generation_publication_status_v1 fail(generation_publication_status_v1 s,std::string*e,const char*m)noexcept{if(e)*e=m;return s;}}
generation_publication_status_v1 validate_generation_publication_v1(const generation_publication_v1&p,std::string*e)noexcept{if(!p.pending_generation||p.pending_generation<=p.current_generation)return fail(generation_publication_status_v1::invalid_generation,e,"pending generation must advance current");if(!valid(p.retained_order.identity))return fail(generation_publication_status_v1::invalid_order,e,"retained order required");std::set<std::tuple<std::uint64_t,std::uint64_t>>ids;bool any_ready=false,any_pending=false;for(const auto&c:p.components){if(!valid(c.identity)||c.generation!=p.pending_generation||!ids.emplace(c.identity.high,c.identity.low).second)return fail(generation_publication_status_v1::invalid_component,e,"unique component at pending generation required");any_ready|=c.state==component_readiness_v1::ready;any_pending|=c.state==component_readiness_v1::preparing;}if(p.published&&any_pending)return fail(generation_publication_status_v1::partial_publication,e,"partial generation cannot be published");if(any_ready&&any_pending&&p.published)return fail(generation_publication_status_v1::partial_publication,e,"mixed readiness publication forbidden");if(e)e->clear();return any_pending?generation_publication_status_v1::component_pending:generation_publication_status_v1::ready;}
generation_publication_status_v1 publish_generation_v1(generation_publication_v1*p,std::string*e)noexcept{if(!p)return fail(generation_publication_status_v1::invalid_generation,e,"publication required");if(p->published)return fail(generation_publication_status_v1::already_published,e,"generation already published");auto s=validate_generation_publication_v1(*p,e);if(s!=generation_publication_status_v1::ready)return s;p->current_generation=p->pending_generation;p->pending_generation=0;p->published=true;if(e)e->clear();return generation_publication_status_v1::ready;}
} // namespace cellerator::compiler::ir::realization::v1
